/**
 * M20-T08 conformance of the WebAssembly backends (ADR-0061), generate step, run by `m20-wasm-conformance.sh` on
 * sv-internal: every golden and conformance case of the contracts fixtures is generated by the codegen service's
 * `/wasm/generate` with its scenario as the test case. Goldens expect exactly `expected.writes.json` and the whole
 * `expected.trace.json` in order. The shell then builds each case in toolchain-wasm and runs `sv-wasm-host --test`.
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const lang = process.env.LANG_ID ?? "cpp";
const C = lang === "rust" ? "http://codegen-rust:4130" : "http://codegen-cpp:4110";
const out = process.env.OUT ?? "/out";
const fixtures = "/repo/modules/simvehicleapp-contracts/fixtures";
const h = { "x-sv-internal": process.env.INTERNAL_API_SECRET ?? "", "content-type": "application/json" };
const pascal = (s: string) => s.replace(/(^|[^A-Za-z0-9]+)([A-Za-z0-9])/g, (_m, _a, c: string) => c.toUpperCase()).replace(/^[^A-Za-z]+/, "") || "App";

let n = 0;
for (const kind of ["golden", "conformance"]) {
  for (const id of readdirSync(join(fixtures, kind)).filter((d) => /^(GW-|C\d)/.test(d)).sort()) {
    const ir = JSON.parse(readFileSync(join(fixtures, kind, id, "ir.json"), "utf8"));
    const scenario = Bun.YAML.parse(readFileSync(join(fixtures, kind, id, "scenario.yaml"), "utf8")) as Record<string, unknown> & { expect?: Record<string, unknown> };
    if (kind === "golden") {
      const writes = JSON.parse(readFileSync(join(fixtures, kind, id, "expected.writes.json"), "utf8"));
      // The whole trace in order, without the run id and sequence of the simulator's run (the guest runs it as "test").
      const trace = (JSON.parse(readFileSync(join(fixtures, kind, id, "expected.trace.json"), "utf8")) as Record<string, unknown>[]).map(({ runId: _r, seq: _s, ...e }) => e);
      scenario.expect = { ...(scenario.expect ?? {}), writes, trace };
    }
    const res = await fetch(`${C}/wasm/generate`, {
      method: "POST",
      headers: h,
      body: JSON.stringify({
        project: { slug: id.toLowerCase(), appName: `${pascal(ir.name)}App`, language: lang, mqttTopicPrefix: `simvehicleapp/${id.toLowerCase()}`, traceLevel: "node" },
        workflows: [ir],
        options: { emitTests: true },
        scenarios: [{ workflowId: ir.workflowId, scenario, caseName: id }],
      }),
    });
    if (res.status !== 200) {
      console.log(`SKIP ${id}: generate ⇒ ${res.status} ${(await res.text()).slice(0, 200)}`);
      continue;
    }
    const fs = (await res.json()) as { files: { path: string; content: string }[] };
    for (const f of fs.files) {
      const p = join(out, id, f.path);
      mkdirSync(dirname(p), { recursive: true });
      writeFileSync(p, f.content);
    }
    n++;
  }
}
console.log(`generated ${n} cases for ${lang}-wasm`);
